WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.AnswerCount, u.DisplayName AS OwnerName, RANK() OVER (ORDER BY p.Score DESC NULLS FIRST, p.CreationDate ASC) AS ScoreRank FROM Posts AS p JOIN Users AS u ON p.OwnerUserId = u.Id WHERE p.PostTypeId = 1 AND NOT (p.Score IS NULL)), PostTags AS (SELECT p.Id AS PostId, GROUP_CONCAT(t.TagName, ', ') AS Tags FROM Posts AS p JOIN Tags AS t ON p.Tags LIKE CONCAT('%', COALESCE(t.TagName, ''), '%') WHERE p.PostTypeId = 1 GROUP BY p.Id), PostComments AS (SELECT PostId, COUNT(*) AS CommentCount FROM Comments GROUP BY PostId) SELECT rp.PostId, rp.Title, rp.OwnerName, rp.CreationDate, rp.Score, rp.ScoreRank, COALESCE(pt.Tags, 'No Tags') AS Tags, COALESCE(pc.CommentCount, 0) AS CommentCount, CASE WHEN rp.AnswerCount > 0 THEN 'Has Answers' ELSE 'No Answers' END AS AnswerStatus FROM RankedPosts AS rp LEFT JOIN PostTags AS pt ON rp.PostId = pt.PostId LEFT JOIN PostComments AS pc ON rp.PostId = pc.PostId WHERE rp.ScoreRank <= 10 ORDER BY rp.Score DESC NULLS FIRST, rp.CreationDate ASC